WITH flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM transactions), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT id, account_id, amount, txn_time, merchant, is_flagged, burst_id, CASE WHEN merchant RLIKE '^(Starbucks|Lazada)$' THEN 'OTHER_ZONE' WHEN merchant RLIKE '^(Grab|7-Eleven)$' THEN 'EXTENDED' ELSE 'GROUP_A' END AS merchant_zone FROM islands ORDER BY amount ASC
